/* cmdlink — construct a real native-prefix .cmd executable. */
#define _GNU_SOURCE
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include "../format/cmd-format.h"

typedef struct { uint32_t h[8]; uint64_t bits; uint8_t b[64]; size_t n; } sha256_ctx;
static const uint32_t K[64]={0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x2e1b2138,0x4d2c6dfc,0x5b9cca4f,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};
#define R(x,n)((x>>n)|(x<<(32-n)))
#define CH(x,y,z)((x&y)^(~x&z))
#define MA(x,y,z)((x&y)^(x&z)^(y&z))
#define E0(x)(R(x,2)^R(x,13)^R(x,22))
#define E1(x)(R(x,6)^R(x,11)^R(x,25))
#define G0(x)(R(x,7)^R(x,18)^(x>>3))
#define G1(x)(R(x,17)^R(x,19)^(x>>10))
static void shinit(sha256_ctx*c){uint32_t h[]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};memcpy(c->h,h,sizeof h);c->bits=0;c->n=0;}
static void shblk(sha256_ctx*c,const uint8_t*p){uint32_t w[64],a,b,d,e,f,g,h,x,t;int i;for(i=0;i<16;i++)w[i]=((uint32_t)p[i*4]<<24)|((uint32_t)p[i*4+1]<<16)|((uint32_t)p[i*4+2]<<8)|p[i*4+3];for(;i<64;i++)w[i]=G1(w[i-2])+w[i-7]+G0(w[i-15])+w[i-16];a=c->h[0];b=c->h[1];x=c->h[2];d=c->h[3];e=c->h[4];f=c->h[5];g=c->h[6];h=c->h[7];for(i=0;i<64;i++){t=h+E1(e)+CH(e,f,g)+K[i]+w[i];uint32_t u=E0(a)+MA(a,b,x);h=g;g=f;f=e;e=d+t;d=x;x=b;b=a;a=t+u;}c->h[0]+=a;c->h[1]+=b;c->h[2]+=x;c->h[3]+=d;c->h[4]+=e;c->h[5]+=f;c->h[6]+=g;c->h[7]+=h;}
static void shupd(sha256_ctx*c,const uint8_t*p,size_t n){c->bits+=(uint64_t)n*8;while(n){size_t k=64-c->n;if(k>n)k=n;memcpy(c->b+c->n,p,k);c->n+=k;p+=k;n-=k;if(c->n==64){shblk(c,c->b);c->n=0;}}}
static void shfin(sha256_ctx*c,uint8_t o[32]){size_t i=c->n;c->b[i++]=0x80;while(i!=56){if(i==64){shblk(c,c->b);i=0;}c->b[i++]=0;}for(int j=0;j<8;j++)c->b[63-j]=(uint8_t)(c->bits>>(j*8));shblk(c,c->b);for(i=0;i<8;i++){o[i*4]=(uint8_t)(c->h[i]>>24);o[i*4+1]=(uint8_t)(c->h[i]>>16);o[i*4+2]=(uint8_t)(c->h[i]>>8);o[i*4+3]=(uint8_t)c->h[i];}}
static uint8_t*readfile(const char*p,size_t*n){FILE*f=fopen(p,"rb");if(!f)return NULL;if(fseek(f,0,SEEK_END)||ftell(f)<0){fclose(f);return NULL;}long z=ftell(f);rewind(f);uint8_t*b=malloc((size_t)z);if(!b){fclose(f);return NULL;}if(fread(b,1,(size_t)z,f)!=(size_t)z){free(b);fclose(f);return NULL;}fclose(f);*n=(size_t)z;return b;}
static int append(FILE*out,const void*p,size_t n){return n&&fwrite(p,1,n,out)!=n?-1:0;}
static char*json_escape(const char*s){size_t n=2;for(const char*p=s?p:"";*p;p++)n+=(*p=='"'||*p=='\\')?2:1;char*r=malloc(n+1),*q=r;if(!r)return NULL;*q++='"';for(const char*p=s?s:"";*p;p++){if(*p=='"'||*p=='\\')*q++='\\';*q++=*p;}*q++='"';*q=0;return r;}
static int make_icon(const char*requested,uint8_t**data,size_t*size){if(requested){*data=readfile(requested,size);return *data?0:-1;}char tmp[]="/tmp/cmd-icon-XXXXXX.bmp";int fd=mkstemps(tmp,4);if(fd<0)return -1;close(fd);char cmd[512];snprintf(cmd,sizeof cmd,"cmd-icon-gen -o '%s' >/dev/null 2>&1",tmp);int rc=system(cmd);if(rc==0)*data=readfile(tmp,size);else *data=NULL;unlink(tmp);return *data?0:-1;}
static int copy_file(FILE*out,const char*p){size_t n;uint8_t*b=readfile(p,&n);if(!b)return -1;int rc=append(out,b,n);free(b);return rc;}
static const char*base_name(const char*p){const char*s=strrchr(p,'/');return s?s+1:p;}
static void usage(const char*p){fprintf(stderr,"Usage: %s <input.class|input.jar> -o <output.cmd> [options]\n\nOptions:\n  --main=<class>         Main class (required for JARs)\n  --icon=<file.bmp>      Embedded icon\n  --xclass=<file>        xmc metadata reference\n  --headless             Mark console application\n  --no-pin               Disable pinning flag\n  --negamane             Mark NEGAMANE\n  --grain=<0-4>          Grain level\n  --perm=<class>         Permission class\n  --graal-hint           Add native-image hint\n  --jvm-args=<args>      JVM arguments\n  --launcher=<file>      Native ELF/PE/Mach-O launcher template\n");}
int main(int argc,char**argv){const char*in=NULL,*outpath=NULL,*mainclass=NULL,*iconpath=NULL,*xclass=NULL,*perm="trusted",*jvm="",*launcher=NULL;int jar=0,headless=0,pin=1,neg=0,grain=0,graal=0;for(int i=1;i<argc;i++){char*a=argv[i];if(!strcmp(a,"--help")||!strcmp(a,"-h")){usage(argv[0]);return 0;}if(!strcmp(a,"-o")&&i+1<argc){outpath=argv[++i];continue;}if(!strncmp(a,"--main=",7)){mainclass=a+7;continue;}if(!strncmp(a,"--icon=",7)){iconpath=a+7;continue;}if(!strncmp(a,"--xclass=",9)){xclass=a+9;continue;}if(!strcmp(a,"--headless")){headless=1;continue;}if(!strcmp(a,"--no-pin")){pin=0;continue;}if(!strcmp(a,"--negamane")){neg=1;continue;}if(!strncmp(a,"--grain=",8)){grain=atoi(a+8);if(grain<0||grain>4){fprintf(stderr,"invalid grain\n");return 2;}continue;}if(!strncmp(a,"--perm=",7)){perm=a+7;continue;}if(!strcmp(a,"--graal-hint")){graal=1;continue;}if(!strncmp(a,"--jvm-args=",11)){jvm=a+11;continue;}if(!strncmp(a,"--launcher=",11)){launcher=a+11;continue;}if(a[0]!='-'){in=a;size_t n=strlen(a);if(n>4&&!strcmp(a+n-4,".jar"))jar=1;continue;}fprintf(stderr,"unknown option: %s\n",a);return 2;}if(!in||!outpath){usage(argv[0]);return 2;}if(!mainclass&&!jar){char*n=strdup(base_name(in));size_t z=strlen(n);if(z>6&&!strcmp(n+z-6,".class")){n[z-6]=0;mainclass=n;}else free(n);}if(jar&&!mainclass){fprintf(stderr,"JAR input requires --main=<class>\n");return 2;}if(!launcher){const char*e=getenv("CMD_LAUNCHER_TEMPLATE");if(e&&*e)launcher=e;else launcher="launcher/linux/cmd-launch-linux";}size_t lsz,isz=0,msz,ssz;uint8_t*ld=readfile(launcher,&lsz);if(!ld){fprintf(stderr,"cannot read native launcher template '%s'\n",launcher);return 1;}size_t csz;uint8_t*cd=readfile(in,&csz);if(!cd){fprintf(stderr,"cannot read '%s'\n",in);free(ld);return 1;}if(jar){if(csz<4||cd[0]!='P'||cd[1]!='K'){fprintf(stderr,"input is not a JAR\n");free(ld);free(cd);return 1;}}else if(csz<4||cd[0]!=0xca||cd[1]!=0xfe||cd[2]!=0xba||cd[3]!=0xbe){fprintf(stderr,"input is not a .class file\n");free(ld);free(cd);return 1;}uint8_t hash[32];sha256_ctx sc;shinit(&sc);shupd(&sc,cd,csz);shfin(&sc,hash);uint8_t*id=NULL;if(iconpath&&!make_icon(iconpath,&id,&isz)){ }else if(!iconpath)make_icon(NULL,&id,&isz);char*mc=json_escape(mainclass?mainclass:"(auto-detect)");char*ja=json_escape(jvm);char*pc=json_escape(perm);char*xs=json_escape(xclass?xclass:"none");if(!mc||!ja||!pc||!xs){fprintf(stderr,"out of memory\n");return 1;}char manifest[8192];int mn=snprintf(manifest,sizeof manifest,"{\n  \"format\": \"cmd\",\n  \"version\": \"1.0\",\n  \"application_name\": \"%s\",\n  \"main_class\": %s,\n  \"jvm_args\": %s,\n  \"jdk_minimum\": 28,\n  \"preferred_runtime\": \"SecureJDK 28\",\n  \"permission_class\": %s,\n  \"grain\": %d,\n  \"pinnable\": %s,\n  \"headless\": %s,\n  \"negamane\": %s,\n  \"graal_native_hint\": %s,\n  \"source_type\": \"%s\",\n  \"xclass_source\": %s\n}\n",base_name(in),mc,ja,pc,grain,pin?"true":"false",headless?"true":"false",neg?"true":"false",graal?"true":"false",jar?"jar":"class",xs);free(mc);free(ja);free(pc);free(xs);if(mn<0||(size_t)mn>=sizeof manifest){fprintf(stderr,"manifest too large\n");return 1;}char hex[65];for(int i=0;i<32;i++)sprintf(hex+i*2,"%02x",hash[i]);hex[64]=0;char security[4096];int sn=snprintf(security,sizeof security,"{\n  \"sha256\": \"%s\",\n  \"integrity_verification\": \"required-before-launch\",\n  \"permission_class\": \"%s\",\n  \"grain_level\": %d,\n  \"negamane_branded\": %s,\n  \"xclass_source\": \"%s\"\n}\n",hex,perm,grain,neg?"true":"false",xclass?xclass:"none");if(sn<0||(size_t)sn>=sizeof security){fprintf(stderr,"security section too large\n");return 1;}size_t hoff=lsz,ioff=hoff+CMD_HEADER_SIZE,moff=ioff+isz,coff=moff+(size_t)mn,soff=coff+csz,total=soff+(size_t)sn;if(total>UINT32_MAX||ioff-hoff>UINT32_MAX||moff-hoff>UINT32_MAX||coff-hoff>UINT32_MAX||soff-hoff>UINT32_MAX){fprintf(stderr,"CMD exceeds 32-bit format limits\n");return 1;}cmd_header_t h={0};h.magic=CMD_MAGIC;h.version=CMD_VERSION;h.flags=(uint16_t)(pin?CMD_FLAG_PINNABLE:0);h.flags|=(uint16_t)(jar?CMD_FLAG_EMBEDDED_JAR:CMD_FLAG_EMBEDDED_CLASS);if(headless)h.flags|=CMD_FLAG_HEADLESS;if(neg)h.flags|=CMD_FLAG_NEGAMANE;if(grain)h.flags|=CMD_FLAG_GRAIN_AWARE;if(graal)h.flags|=CMD_FLAG_NATIVE_IMAGE;h.icon_offset=(uint32_t)(ioff-hoff);h.icon_size=(uint32_t)isz;h.manifest_offset=(uint32_t)(moff-hoff);h.manifest_size=(uint32_t)mn;h.class_offset=(uint32_t)(coff-hoff);h.class_size=(uint32_t)csz;h.security_offset=(uint32_t)(soff-hoff);h.security_size=(uint32_t)sn;memcpy(h.sha256,hash,32);h.jdk_min_version=CMD_MIN_JDK;FILE*f=fopen(outpath,"wb");if(!f){perror(outpath);return 1;}if(append(f,ld,lsz)||append(f,&h,sizeof h)||append(f,id,isz)||append(f,manifest,(size_t)mn)||append(f,cd,csz)||append(f,security,(size_t)sn)){fprintf(stderr,"write failed\n");fclose(f);return 1;}fclose(f);chmod(outpath,0755);printf("Created native CMD: %s\n  launcher: %zu bytes\n  total:    %zu bytes\n  SHA-256:  %s\n",outpath,lsz,total,hex);free(ld);free(cd);free(id);return 0;}
